+// formatting stack frame and carry the recorder's locals in generated Wasm.
+static __attribute__((noinline)) void wasmJitRecordFetchNextTransition(CPU* cpu, DecodedOp* nextOp) {
     U64 total = g_wasmJitTransitionFetchNext.fetch_add(1, std::memory_order_relaxed) + 1;
     if (cpu->yield) {
         g_wasmJitTransitionFetchNextYield.fetch_add(1, std::memory_order_relaxed);

