 // catch(...) exactly as they do for the x32/arm JIT backends.
+// Keep varargs stack preparation behind the first-call condition. Inlining
+// the formatter here otherwise spills tableIndex on every compiled block.
+static __attribute__((noinline)) void wasmJitLogFirstBlock(int tableIndex) {
+    klog_fmt("[WASM JIT] first JIT block executed, tableIdx: %d", tableIndex);
+}
